TYPE E_EtherCATSystemState :
(
    INIT := 0,
    CHECK_BUS := 10,
    OPERATIONAL := 20,
    BUS_FAULT := 99,
    CRC_EXCEEDED := 100
) UDINT;
END_TYPE

TYPE ST_RawHardwareInputs :
STRUCT
    xPhysicalIn00 : BOOL;
    xPhysicalIn01 : BOOL;
    xPhysicalDriveEnableReq : BOOL;
    iPhysicalAnalog00 : INT;
END_STRUCT
END_TYPE

TYPE ST_LogicalMappedIO :
STRUCT
    xSensor1_ConveyorStart : BOOL;
    xSensor2_PartPresent : BOOL;
    rAnalogTemperature : REAL;
END_STRUCT
END_TYPE

TYPE ST_SafetyInterlocks :
STRUCT
    xEStopRelay_K1 : BOOL;
    xThermalOverloadBypass : BOOL;
    xDriveEnable : BOOL;
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_EtherCAT_Diagnostic_Mapping
TITLE = 'EtherCAT Diagnostic and Safety Mapping'
AUTHOR : 'Lumina Elite Architect'
VERSION : '2.0'
// ========================================================================
// DESCRIPTION:
// This function block manages EtherCAT master and slave diagnostics,
// tracks CRC errors, maps raw IO to structured logical data, and 
// implements a safety state machine to handle bus failures securely. 
// It enforces fail-safe conditions by de-energizing critical outputs 
// during bus interruptions.
// ========================================================================

VAR_INPUT
    xEnable : BOOL; // Enable the diagnostic and mapping block
    wMasterState : WORD; // Raw EtherCAT Master State (e.g., INIT, PREOP, SAFEOP, OP)
    arrSlaveStates : ARRAY[1..MAX_SLAVES] OF WORD; // Raw state of each slave
    arrSlaveCRCErrors : ARRAY[1..MAX_SLAVES] OF UDINT; // Cumulative CRC errors per slave
    stRawInputs : ST_RawHardwareInputs; // Raw input bitwise mapping from hardware
    xResetErrors : BOOL; // Reset error latches and safety state
END_VAR

VAR_OUTPUT
    stMappedIO : ST_LogicalMappedIO; // Safely mapped inputs for application use
    stSafetyOutputs : ST_SafetyInterlocks; // Outputs to E-Stops, Thermal Overloads, etc.
    eSystemState : E_EtherCATSystemState; // Current diagnostic state machine state
    xBusFault : BOOL; // Indicates a critical bus fault
    xSafetyTriggered : BOOL; // Indicates fallback safety has been activated
END_VAR

VAR
    i : INT;
    udiTotalCRCErrors : UDINT;
    xMasterInOp : BOOL;
    xAllSlavesInOp : BOOL;

    // Safety latches
    xLatchEStop : BOOL := FALSE;

    // Timers
    tonBusRecovery : TON; 
END_VAR

VAR CONSTANT
    MAX_SLAVES : INT := 16;
    STATE_OP : WORD := 16#08; // Typical EtherCAT OP state value (0x08)
    MAX_CRC_THRESHOLD : UDINT := 500;
END_VAR

BEGIN
    // =========================================================================
    // 1. MASTER AND SLAVE STATE EVALUATION
    // =========================================================================

    // Check if master is in OP state
    xMasterInOp := (wMasterState = STATE_OP);

    // Check if all slaves are in OP state and sum cumulative CRC errors
    xAllSlavesInOp := TRUE;
    udiTotalCRCErrors := 0;

    FOR i := 1 TO MAX_SLAVES DO
        IF arrSlaveStates[i] <> STATE_OP THEN
            xAllSlavesInOp := FALSE;
        END_IF;
        udiTotalCRCErrors := udiTotalCRCErrors + arrSlaveCRCErrors[i];
    END_FOR;

    // =========================================================================
    // 2. DIAGNOSTIC STATE MACHINE
    // =========================================================================
    CASE eSystemState OF
        E_EtherCATSystemState.INIT:
            IF xEnable THEN
                eSystemState := E_EtherCATSystemState.CHECK_BUS;
            END_IF;

        E_EtherCATSystemState.CHECK_BUS:
            IF xMasterInOp AND xAllSlavesInOp THEN
                eSystemState := E_EtherCATSystemState.OPERATIONAL;
                xBusFault := FALSE;
            ELSIF NOT xMasterInOp OR NOT xAllSlavesInOp THEN
                eSystemState := E_EtherCATSystemState.BUS_FAULT;
            END_IF;

        E_EtherCATSystemState.OPERATIONAL:
            // Continuous monitoring for link drops or configuration losses
            IF NOT xMasterInOp OR NOT xAllSlavesInOp THEN
                eSystemState := E_EtherCATSystemState.BUS_FAULT;
            // Track physical layer degradation via CRC frames
            ELSIF udiTotalCRCErrors > MAX_CRC_THRESHOLD THEN
                eSystemState := E_EtherCATSystemState.CRC_EXCEEDED;
            END_IF;

        E_EtherCATSystemState.BUS_FAULT:
            xBusFault := TRUE;
            // Attempt automatic recovery if bus returns to OP, with debounce filtering
            tonBusRecovery(IN := (xMasterInOp AND xAllSlavesInOp), PT := T#2S);
            IF tonBusRecovery.Q THEN
                eSystemState := E_EtherCATSystemState.OPERATIONAL;
                xBusFault := FALSE;
            END_IF;

        E_EtherCATSystemState.CRC_EXCEEDED:
            xBusFault := TRUE;
            // High error count indicates potentially fatal hardware issues (cables, shielding).
            // Requires manual reset.
            IF xResetErrors THEN
                eSystemState := E_EtherCATSystemState.CHECK_BUS;
            END_IF;

    END_CASE;

    // =========================================================================
    // 3. SAFETY INTERLOCKS & FALLBACK OUTPUTS
    // =========================================================================
    // If the bus is faulty, we must immediately trigger a fail-safe state.
    // Critical safety loops (e.g., E-stops) use normally-closed (NC) logic.

    IF (eSystemState = E_EtherCATSystemState.BUS_FAULT) OR (eSystemState = E_EtherCATSystemState.CRC_EXCEEDED) THEN
        xSafetyTriggered := TRUE;
        xLatchEStop := TRUE; // Latch the fault condition
    ELSIF xResetErrors AND NOT xBusFault THEN
        xSafetyTriggered := FALSE;
        xLatchEStop := FALSE;
    END_IF;

    // Enforce output assignments based on safety state
    IF xSafetyTriggered THEN
        // --- FALLBACK STATE: De-energize all critical outputs ---
        stSafetyOutputs.xEStopRelay_K1 := FALSE; // Drop main contactor
        stSafetyOutputs.xThermalOverloadBypass := FALSE;
        stSafetyOutputs.xDriveEnable := FALSE;

        // Zero out mapped logical IO to prevent stale data usage in the application layer
        stMappedIO.xSensor1_ConveyorStart := FALSE;
        stMappedIO.xSensor2_PartPresent := FALSE;
        stMappedIO.rAnalogTemperature := 0.0;
    ELSE
        // --- OPERATIONAL STATE: Normal pass-through and scaling ---
        stSafetyOutputs.xEStopRelay_K1 := TRUE; 
        stSafetyOutputs.xThermalOverloadBypass := TRUE;
        stSafetyOutputs.xDriveEnable := stRawInputs.xPhysicalDriveEnableReq;

        // Abstract physical raw bits to structured logical names
        stMappedIO.xSensor1_ConveyorStart := stRawInputs.xPhysicalIn00;
        stMappedIO.xSensor2_PartPresent := stRawInputs.xPhysicalIn01;

        // Apply engineering scaling to raw analog data (e.g., INT to REAL)
        stMappedIO.rAnalogTemperature := INT_TO_REAL(stRawInputs.iPhysicalAnalog00) * 0.1;
    END_IF;

END_FUNCTION_BLOCK
```

```pascal
(*
=================================================================================================
    FB_FlowWrapper_ECam

    Description: 
    High-speed Flow Wrapper packaging machine controller with Electronic Camming (E-Cam).
    Synchronizes a continuous Film Feed (Master) with Rotary Seal Jaws (Slave).
    Includes safety interlocks, thermal overload monitoring for seal jaws, and a robust 
    state machine for normal operation and fault handling.

    Dependencies: Tc2_MC2 (TwinCAT Motion Control)
    Author: Lumina Synthetic Data Architect
    Date: 2026-08-21
=================================================================================================
*)
TYPE E_FlowWrapperState :
(
    INIT := 0,
    CHECK_SAFETY := 10,
    ENABLE_AXES := 20,
    WAIT_FOR_START := 30,
    ENGAGE_CAM := 40,
    START_FILM_FEED := 50,
    PRODUCTION_RUN := 60,
    STOPPING := 70,
    DISENGAGE_CAM := 80,
    ERROR := 999
);
END_TYPE

FUNCTION_BLOCK FB_FlowWrapper_ECam
VAR_INPUT
    bEnable             : BOOL;           // Master enable signal
    bStart              : BOOL;           // Start production cycle
    bStop               : BOOL;           // Stop production cycle gracefully
    bEStop              : BOOL;           // Emergency Stop (Active LOW, normally closed)
    bGuardDoorsClosed   : BOOL;           // Guard doors interlock (Active HIGH)

    // Hardware Sensors / Overloads
    bThermalOverloadJaw : BOOL;           // Seal jaw thermal overload (Active LOW)
    bProductDetected    : BOOL;           // Product infeed registration sensor

    // Cam Table Reference
    CamTableID          : MC_CAM_ID;      // Reference to the defined cam table for jaws

    // Process Parameters
    fFilmVelocity       : LREAL := 500.0; // mm/s for continuous film feed
END_VAR

VAR_IN_OUT
    AxisFilmFeed        : AXIS_REF;       // Master Axis (Film)
    AxisRotaryJaws      : AXIS_REF;       // Slave Axis (Seal Jaws)
END_VAR

VAR_OUTPUT
    bReady              : BOOL;           // Machine is initialized and ready
    bRunning            : BOOL;           // Production is active
    bError              : BOOL;           // General error flag
    eState              : E_FlowWrapperState; // Current machine state
    sErrorMsg           : STRING;         // Detailed error description
END_VAR

VAR
    // State Machine
    eNextState          : E_FlowWrapperState := E_FlowWrapperState.INIT;

    // Motion Control Function Blocks (TwinCAT MC2)
    fbFilmPower         : MC_Power;
    fbJawsPower         : MC_Power;
    fbFilmReset         : MC_Reset;
    fbJawsReset         : MC_Reset;
    fbFilmMoveVelocity  : MC_MoveVelocity;
    fbFilmStop          : MC_Stop;
    fbJawsStop          : MC_Stop;
    fbCamIn             : MC_CamIn;
    fbCamOut            : MC_CamOut;

    // Internal Variables
    bAxesEnabled        : BOOL;
    bSafetyOK           : BOOL;
    rtStart             : R_TRIG;
    rtStop              : R_TRIG;
END_VAR

// ----------------------------------------------------------------------
// IMPLEMENTATION
// ----------------------------------------------------------------------

// 1. Safety & Interlock Evaluation
// Fail-safe logic: e-stops and overloads are Active LOW (must be TRUE to operate)
bSafetyOK := bEStop AND bThermalOverloadJaw AND bGuardDoorsClosed;

IF NOT bSafetyOK AND eState <> E_FlowWrapperState.ERROR THEN
    eState := E_FlowWrapperState.ERROR;
    sErrorMsg := 'SAFETY INTERLOCK TRIPPED OR E-STOP PRESSED';
END_IF

// 2. Edge Detections
rtStart(CLK := bStart);
rtStop(CLK := bStop);

// 3. State Machine
CASE eState OF
    E_FlowWrapperState.INIT:
        bReady := FALSE;
        bRunning := FALSE;
        bError := FALSE;
        sErrorMsg := '';

        fbFilmMoveVelocity.Execute := FALSE;
        fbCamIn.Execute := FALSE;
        fbCamOut.Execute := FALSE;
        fbFilmStop.Execute := FALSE;
        fbJawsStop.Execute := FALSE;

        IF bEnable THEN
            eState := E_FlowWrapperState.CHECK_SAFETY;
        END_IF

    E_FlowWrapperState.CHECK_SAFETY:
        IF bSafetyOK THEN
            eState := E_FlowWrapperState.ENABLE_AXES;
        END_IF

    E_FlowWrapperState.ENABLE_AXES:
        // Turn on power to both axes
        fbFilmPower.Enable := TRUE;
        fbFilmPower.Enable_Positive := TRUE;
        fbFilmPower.Enable_Negative := TRUE;

        fbJawsPower.Enable := TRUE;
        fbJawsPower.Enable_Positive := TRUE;
        fbJawsPower.Enable_Negative := TRUE;

        IF fbFilmPower.Status AND fbJawsPower.Status THEN
            bReady := TRUE;
            eState := E_FlowWrapperState.WAIT_FOR_START;
        END_IF

    E_FlowWrapperState.WAIT_FOR_START:
        IF rtStart.Q AND bSafetyOK THEN
            bReady := FALSE;
            eState := E_FlowWrapperState.ENGAGE_CAM;
        END_IF

    E_FlowWrapperState.ENGAGE_CAM:
        // Engage the electronic cam coupling first before moving the master
        fbCamIn.MasterOffset := 0.0;
        fbCamIn.SlaveOffset := 0.0;
        fbCamIn.Execute := TRUE;

        IF fbCamIn.InSync THEN
            fbCamIn.Execute := FALSE;
            eState := E_FlowWrapperState.START_FILM_FEED;
        ELSIF fbCamIn.Error THEN
            sErrorMsg := 'CAM IN ERROR';
            eState := E_FlowWrapperState.ERROR;
        END_IF

    E_FlowWrapperState.START_FILM_FEED:
        // Accelerate the master axis (film) to target velocity
        fbFilmMoveVelocity.Velocity := fFilmVelocity;
        fbFilmMoveVelocity.Acceleration := 1000.0;
        fbFilmMoveVelocity.Deceleration := 1000.0;
        fbFilmMoveVelocity.Jerk := 5000.0;
        fbFilmMoveVelocity.Direction := MC_Positive_Direction;
        fbFilmMoveVelocity.Execute := TRUE;

        IF fbFilmMoveVelocity.InVelocity THEN
            bRunning := TRUE;
            eState := E_FlowWrapperState.PRODUCTION_RUN;
        ELSIF fbFilmMoveVelocity.Error THEN
            sErrorMsg := 'FILM FEED MOTION ERROR';
            eState := E_FlowWrapperState.ERROR;
        END_IF

    E_FlowWrapperState.PRODUCTION_RUN:
        // Normal continuous operation
        // Jaws are cammed to the film feed, executing seal/cut cyclically

        IF rtStop.Q OR NOT bEnable THEN
            bRunning := FALSE;
            fbFilmMoveVelocity.Execute := FALSE;
            eState := E_FlowWrapperState.STOPPING;
        END_IF

    E_FlowWrapperState.STOPPING:
        // Stop the master axis, slave will follow synchronously
        fbFilmStop.Deceleration := 1000.0;
        fbFilmStop.Jerk := 5000.0;
        fbFilmStop.Execute := TRUE;

        IF fbFilmStop.Done THEN
            fbFilmStop.Execute := FALSE;
            eState := E_FlowWrapperState.DISENGAGE_CAM;
        END_IF

    E_FlowWrapperState.DISENGAGE_CAM:
        fbCamOut.Execute := TRUE;

        IF fbCamOut.Done THEN
            fbCamOut.Execute := FALSE;
            eState := E_FlowWrapperState.INIT; // Return to init
        END_IF

    E_FlowWrapperState.ERROR:
        bError := TRUE;
        bReady := FALSE;
        bRunning := FALSE;

        // Disable axes safely
        fbFilmPower.Enable := FALSE;
        fbJawsPower.Enable := FALSE;

        // Execute stopping if still moving (for graceful error handling if not e-stop)
        fbFilmStop.Execute := TRUE;
        fbJawsStop.Execute := TRUE;

        // Reset Logic
        IF bEnable = FALSE AND bSafetyOK THEN // Wait for toggle
            fbFilmReset.Execute := TRUE;
            fbJawsReset.Execute := TRUE;

            IF fbFilmReset.Done AND fbJawsReset.Done THEN
                fbFilmReset.Execute := FALSE;
                fbJawsReset.Execute := FALSE;
                bError := FALSE;
                fbFilmStop.Execute := FALSE;
                fbJawsStop.Execute := FALSE;
                eState := E_FlowWrapperState.INIT;
            END_IF
        END_IF

END_CASE

// 4. Update Motion Control Blocks
fbFilmPower(Axis := AxisFilmFeed);
fbJawsPower(Axis := AxisRotaryJaws);

fbFilmReset(Axis := AxisFilmFeed);
fbJawsReset(Axis := AxisRotaryJaws);

fbFilmMoveVelocity(Axis := AxisFilmFeed);

// Camming blocks take both Master and Slave references
fbCamIn(Master := AxisFilmFeed, Slave := AxisRotaryJaws, CamTableID := CamTableID);
fbCamOut(Slave := AxisRotaryJaws);

fbFilmStop(Axis := AxisFilmFeed);
fbJawsStop(Axis := AxisRotaryJaws);
```

(* 
   =============================================================================
   Lumina Elite Synthetic Data Architect - IEC 61131-3 Advanced MPC Module
   =============================================================================
   Module: FB_Distillation_MPC
   Description: 
   Model Predictive Control (MPC) for an Oil & Gas fractional distillation 
   column. This block evaluates a prediction matrix over a finite horizon 
   to optimize the Reflux Ratio and Bottoms Flow, while respecting stringent 
   safety overrides (High Pressure, Thermal Overload, E-Stop).

   Hardware Abstraction Layer (HAL) inputs are utilized for sensor readings 
   and actuator commands. 
   =============================================================================
*)

TYPE UDT_MPC_Matrix :
    STRUCT
        A : ARRAY[1..3, 1..3] OF REAL; (* System Matrix *)
        B : ARRAY[1..3, 1..2] OF REAL; (* Control Matrix *)
        C : ARRAY[1..2, 1..3] OF REAL; (* Output Matrix *)
    END_STRUCT
END_TYPE

TYPE UDT_Sensor_HAL :
    STRUCT
        ColumnPressure      : REAL;  (* bar *)
        TopTemperature      : REAL;  (* deg C *)
        BottomTemperature   : REAL;  (* deg C *)
        FeedFlowRate        : REAL;  (* m3/h *)
        E_Stop_Active       : BOOL;  (* TRUE = E-Stop triggered *)
        ThermalOverload     : BOOL;  (* TRUE = Reboiler tripped *)
    END_STRUCT
END_TYPE

TYPE UDT_Actuator_HAL :
    STRUCT
        RefluxValveCmd      : REAL;  (* 0-100% *)
        BottomsValveCmd     : REAL;  (* 0-100% *)
        ReboilerHeaterCmd   : REAL;  (* 0-100% *)
        SafetyVentOpen      : BOOL;  (* TRUE = Vent Open *)
    END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_Distillation_MPC
VAR_INPUT
    Sensors          : UDT_Sensor_HAL;
    SetpointTopTemp  : REAL := 65.0;
    SetpointBotTemp  : REAL := 150.0;
    MaxPressure      : REAL := 5.0;   (* bar *)
    MPC_Config       : UDT_MPC_Matrix;
    EnableControl    : BOOL;
END_VAR

VAR_OUTPUT
    Actuators        : UDT_Actuator_HAL;
    SystemFault      : BOOL;
    State            : INT;           (* 0=Idle, 1=Running, 2=Fault, 3=Safe_State *)
    CalcRefluxRatio  : REAL;
END_VAR

VAR
    StateVec         : ARRAY[1..3] OF REAL; (* x(k) *)
    NextStateVec     : ARRAY[1..3] OF REAL; (* x(k+1) *)
    ControlVec       : ARRAY[1..2] OF REAL; (* u(k) *)
    OutputVec        : ARRAY[1..2] OF REAL; (* y(k) *)

    ErrorTop         : REAL;
    ErrorBot         : REAL;

    i, j             : INT;
    TempSum          : REAL;

    (* Safety State Machine *)
    bHighPressureAlarm : BOOL;
    bCriticalFault     : BOOL;
END_VAR

BEGIN
    (* ---------------------------------------------------------------------- *)
    (* 1. Safety Interlocks & Hardware Overrides                              *)
    (* ---------------------------------------------------------------------- *)
    bHighPressureAlarm := Sensors.ColumnPressure > MaxPressure;
    bCriticalFault := Sensors.E_Stop_Active OR Sensors.ThermalOverload OR bHighPressureAlarm;

    IF bCriticalFault THEN
        SystemFault := TRUE;
        State := 3; (* Safe State *)
    ELSIF NOT EnableControl THEN
        SystemFault := FALSE;
        State := 0; (* Idle *)
    ELSE
        SystemFault := FALSE;
        State := 1; (* Running *)
    END_IF;

    (* ---------------------------------------------------------------------- *)
    (* 2. State Machine Execution                                             *)
    (* ---------------------------------------------------------------------- *)
    CASE State OF
        0: (* Idle State *)
            Actuators.RefluxValveCmd := 0.0;
            Actuators.BottomsValveCmd := 0.0;
            Actuators.ReboilerHeaterCmd := 0.0;
            Actuators.SafetyVentOpen := FALSE;
            CalcRefluxRatio := 0.0;

        1: (* Running State - MPC Matrix Calculation *)

            (* Map sensors to state vector (Simplified Observer) *)
            StateVec[1] := Sensors.TopTemperature;
            StateVec[2] := Sensors.BottomTemperature;
            StateVec[3] := Sensors.FeedFlowRate;

            ErrorTop := SetpointTopTemp - StateVec[1];
            ErrorBot := SetpointBotTemp - StateVec[2];

            (* Calculate Control Vector u(k) = K * e(k) *)
            ControlVec[1] := ErrorTop * 0.5 + ErrorBot * 0.1; (* Reflux influence *)
            ControlVec[2] := ErrorTop * 0.1 + ErrorBot * 0.6; (* Bottoms influence *)

            (* Matrix Multiplication: x(k+1) = A*x(k) + B*u(k) *)
            FOR i := 1 TO 3 DO
                TempSum := 0.0;
                (* A * x(k) *)
                FOR j := 1 TO 3 DO
                    TempSum := TempSum + (MPC_Config.A[i, j] * StateVec[j]);
                END_FOR;

                (* B * u(k) *)
                FOR j := 1 TO 2 DO
                    TempSum := TempSum + (MPC_Config.B[i, j] * ControlVec[j]);
                END_FOR;

                NextStateVec[i] := TempSum;
            END_FOR;

            (* Calculate output y(k) = C * x(k) *)
            FOR i := 1 TO 2 DO
                TempSum := 0.0;
                FOR j := 1 TO 3 DO
                    TempSum := TempSum + (MPC_Config.C[i, j] * NextStateVec[j]);
                END_FOR;
                OutputVec[i] := TempSum;
            END_FOR;

            (* Reflux Ratio Calculation (L/D) based on predicted outputs *)
            IF OutputVec[2] > 0.1 THEN
                CalcRefluxRatio := OutputVec[1] / OutputVec[2];
            ELSE
                CalcRefluxRatio := 10.0; (* Clamp to max logical ratio *)
            END_IF;

            (* Map calculated control actions to Actuator HAL *)
            Actuators.RefluxValveCmd := ControlVec[1];
            Actuators.BottomsValveCmd := ControlVec[2];

            (* Basic Heater control based on Bottoms error *)
            Actuators.ReboilerHeaterCmd := ErrorBot * 2.0;

            (* Clamp Outputs 0-100% *)
            IF Actuators.RefluxValveCmd > 100.0 THEN Actuators.RefluxValveCmd := 100.0; END_IF;
            IF Actuators.RefluxValveCmd < 0.0 THEN Actuators.RefluxValveCmd := 0.0; END_IF;
            IF Actuators.BottomsValveCmd > 100.0 THEN Actuators.BottomsValveCmd := 100.0; END_IF;
            IF Actuators.BottomsValveCmd < 0.0 THEN Actuators.BottomsValveCmd := 0.0; END_IF;
            IF Actuators.ReboilerHeaterCmd > 100.0 THEN Actuators.ReboilerHeaterCmd := 100.0; END_IF;
            IF Actuators.ReboilerHeaterCmd < 0.0 THEN Actuators.ReboilerHeaterCmd := 0.0; END_IF;

            Actuators.SafetyVentOpen := FALSE;

        3: (* Safe State - Critical Overrides Active *)
            Actuators.RefluxValveCmd := 100.0;  (* Full reflux to cool column *)
            Actuators.BottomsValveCmd := 100.0; (* Drain bottoms *)
            Actuators.ReboilerHeaterCmd := 0.0; (* Kill heat source immediately *)

            (* If high pressure caused the trip, open the safety relief vent *)
            IF bHighPressureAlarm THEN
                Actuators.SafetyVentOpen := TRUE;
            ELSE
                Actuators.SafetyVentOpen := FALSE;
            END_IF;
            CalcRefluxRatio := 0.0;

    END_CASE;
END_FUNCTION_BLOCK

(*
    ======================================================================================
    LUMINA ELITE SYNTHETIC DATA ARCHITECT
    Block: FB_ASRS_CoordinateMapper
    Description: 
        Advanced Logistics Automated Storage and Retrieval System (ASRS) coordinate 
        mapper and controller. Maps 1D index addresses to 3D rack coordinates (X, Y, Z), 
        tracks bin statuses (Empty, Full, Reserved), handles crane shortest-path 
        calculations, and includes comprehensive safety interlocks and thermal monitoring.
    ======================================================================================
*)
TYPE
    E_BinStatus : (
        BIN_EMPTY,
        BIN_FULL,
        BIN_RESERVED_PUTAWAY,
        BIN_RESERVED_PICK
    );

    E_CraneState : (
        CRANE_INIT,
        CRANE_IDLE,
        CRANE_CALC_PATH,
        CRANE_MOVING_X,
        CRANE_MOVING_Y,
        CRANE_MOVING_Z,
        CRANE_EXTRACTING,
        CRANE_INSERTING,
        CRANE_FAULT,
        CRANE_SAFE_STOP
    );

    ST_3D_Coordinate : STRUCT
        X : REAL; (* Horizontal track position [mm] *)
        Y : REAL; (* Vertical mast position [mm] *)
        Z : REAL; (* Depth fork extension [mm] *)
    END_STRUCT;

    ST_BinData : STRUCT
        Status : E_BinStatus;
        WeightKg : REAL;
        LastUpdated : DATE_AND_TIME;
    END_STRUCT;
END_TYPE

FUNCTION_BLOCK FB_ASRS_CoordinateMapper
VAR_INPUT
    bEnable          : BOOL;  (* System enable *)
    bEstop           : BOOL;  (* Emergency Stop (Active LOW) *)
    bThermalOverload : BOOL;  (* Thermal Overload Sensor (Active HIGH) *)
    bDriveHealthy    : BOOL;  (* Drives healthy status *)

    nTargetBinIndex  : DINT;  (* 1D Target Bin Index (1 to MAX_BINS) *)
    bRequestPutaway  : BOOL;  (* Request to put a tote into rack *)
    bRequestPick     : BOOL;  (* Request to extract a tote from rack *)
    bResetFault      : BOOL;  (* Reset active faults *)

    stCurrentPos     : ST_3D_Coordinate; (* Crane real-time position from encoders *)
END_VAR

VAR_OUTPUT
    eState           : E_CraneState;
    bReady           : BOOL;  (* System ready for new commands *)
    bFault           : BOOL;  (* System faulted *)
    nFaultID         : INT;   (* Fault code *)

    stTargetPos      : ST_3D_Coordinate; (* Output setpoint for servo drives *)
    fDistanceToTarget: REAL;  (* Shortest path calculated distance in mm *)
END_VAR

VAR
    (* Rack Dimensions and Parameters *)
    c_MaxColumns : DINT := 100;
    c_MaxRows    : DINT := 20;
    c_MaxDepths  : DINT := 2;   (* Double-deep storage *)

    c_CellWidth  : REAL := 500.0; (* mm *)
    c_CellHeight : REAL := 400.0; (* mm *)
    c_CellDepth  : REAL := 600.0; (* mm *)

    (* Internal State *)
    aBinMatrix   : ARRAY[1..100, 1..20, 1..2] OF ST_BinData;
    nTargetX_Idx : DINT;
    nTargetY_Idx : DINT;
    nTargetZ_Idx : DINT;

    bSafetyOK    : BOOL;
END_VAR

(* 
    ======================================================================================
    1. SAFETY INTERLOCKS AND DIAGNOSTICS
    ======================================================================================
*)
bSafetyOK := (bEstop = TRUE) AND NOT bThermalOverload AND bDriveHealthy;

IF NOT bSafetyOK THEN
    eState := CRANE_SAFE_STOP;
    bFault := TRUE;
    IF NOT bEstop THEN nFaultID := 101; (* E-Stop pressed *)
    ELSIF bThermalOverload THEN nFaultID := 102; (* Thermal trip *)
    ELSIF NOT bDriveHealthy THEN nFaultID := 103; (* Drive error *)
    END_IF;
END_IF;

IF bResetFault AND bSafetyOK THEN
    bFault := FALSE;
    nFaultID := 0;
    eState := CRANE_INIT;
END_IF;

(* 
    ======================================================================================
    2. STATE MACHINE: CRANE CONTROL
    ======================================================================================
*)
CASE eState OF

    CRANE_INIT:
        IF bEnable AND bSafetyOK THEN
            bReady := TRUE;
            eState := CRANE_IDLE;
        END_IF;

    CRANE_IDLE:
        bReady := TRUE;

        IF (bRequestPutaway OR bRequestPick) AND nTargetBinIndex >= 1 AND nTargetBinIndex <= (c_MaxColumns * c_MaxRows * c_MaxDepths) THEN
            bReady := FALSE;

            (* Reverse map 1D Index to 3D Array Indices (Col, Row, Depth) *)
            nTargetX_Idx := ((nTargetBinIndex - 1) / (c_MaxRows * c_MaxDepths)) + 1;
            nTargetY_Idx := (((nTargetBinIndex - 1) / c_MaxDepths) MOD c_MaxRows) + 1;
            nTargetZ_Idx := ((nTargetBinIndex - 1) MOD c_MaxDepths) + 1;

            (* Check Bin Status Validity *)
            IF bRequestPutaway AND aBinMatrix[nTargetX_Idx, nTargetY_Idx, nTargetZ_Idx].Status = BIN_EMPTY THEN
                aBinMatrix[nTargetX_Idx, nTargetY_Idx, nTargetZ_Idx].Status := BIN_RESERVED_PUTAWAY;
                eState := CRANE_CALC_PATH;

            ELSIF bRequestPick AND aBinMatrix[nTargetX_Idx, nTargetY_Idx, nTargetZ_Idx].Status = BIN_FULL THEN
                aBinMatrix[nTargetX_Idx, nTargetY_Idx, nTargetZ_Idx].Status := BIN_RESERVED_PICK;
                eState := CRANE_CALC_PATH;

            ELSE
                bFault := TRUE;
                nFaultID := 201; (* Invalid Bin Status for requested operation *)
                eState := CRANE_FAULT;
            END_IF;
        END_IF;

    CRANE_CALC_PATH:
        (* Calculate physical coordinates (Target Setpoints) *)
        stTargetPos.X := DINT_TO_REAL(nTargetX_Idx - 1) * c_CellWidth;
        stTargetPos.Y := DINT_TO_REAL(nTargetY_Idx - 1) * c_CellHeight;
        stTargetPos.Z := DINT_TO_REAL(nTargetZ_Idx - 1) * c_CellDepth;

        (* Calculate Shortest Path Euclidean Distance *)
        fDistanceToTarget := SQRT(
            EXPT((stTargetPos.X - stCurrentPos.X), 2.0) +
            EXPT((stTargetPos.Y - stCurrentPos.Y), 2.0) +
            EXPT((stTargetPos.Z - stCurrentPos.Z), 2.0)
        );

        (* Proceed to movement sequence *)
        eState := CRANE_MOVING_X;

    CRANE_MOVING_X:
        (* Simulate wait for X position reached *)
        IF ABS(stCurrentPos.X - stTargetPos.X) < 1.0 THEN
            eState := CRANE_MOVING_Y;
        END_IF;

    CRANE_MOVING_Y:
        IF ABS(stCurrentPos.Y - stTargetPos.Y) < 1.0 THEN
            IF bRequestPutaway THEN
                eState := CRANE_INSERTING;
            ELSE
                eState := CRANE_EXTRACTING;
            END_IF;
        END_IF;

    CRANE_INSERTING:
        (* Finalize Putaway *)
        aBinMatrix[nTargetX_Idx, nTargetY_Idx, nTargetZ_Idx].Status := BIN_FULL;
        eState := CRANE_IDLE;

    CRANE_EXTRACTING:
        (* Finalize Pick *)
        aBinMatrix[nTargetX_Idx, nTargetY_Idx, nTargetZ_Idx].Status := BIN_EMPTY;
        eState := CRANE_IDLE;

    CRANE_FAULT:
        (* Requires bResetFault to clear *)
        bReady := FALSE;

    CRANE_SAFE_STOP:
        (* Hardware interlocks open - immediate halt mapped externally *)
        bReady := FALSE;
        stTargetPos := stCurrentPos; (* Zero out movement deltas *)

END_CASE;
END_FUNCTION_BLOCK

Here is the evolved implementation of an ultra-precise Semiconductor Wafer Handling Robot Sequencer in IEC 61131-3 Structured Text. This implementation transforms a basic state machine into a complex sequencer tailored for semiconductor manufacturing (e.g., FOUP handling, EFEM operations). It features hardware abstractions, SECS/GEM host communication mapping, safety interlocks, and a robust state machine for the load/unload sequence.

```pascal
TYPE
    // SECS/GEM Host Communication Data Mapping
    UDT_SECS_GEM_Interface : STRUCT
        HostCommand : INT;           // 0=None, 1=LoadFOUP, 2=UnloadFOUP, 3=TransferWafer, 4=Abort
        HostStateRequest : BOOL;     // Request current equipment state
        EquipmentState : INT;        // 1=IDLE, 2=EXECUTING, 3=PAUSED, 4=FAULTED
        FoupID : STRING[32];         // Current FOUP ID
        WaferSlot : INT;             // Target wafer slot (1-25)
        ErrorCode : INT;             // SECS/GEM defined error code mapping
        EventReport : BOOL;          // Trigger CEID (Collection Event ID) report
    END_STRUCT;

    // Hardware Abstraction Layer
    UDT_Robot_Hardware : STRUCT
        AxisX_Pos : REAL;            // R-Theta X Axis
        AxisY_Pos : REAL;            // R-Theta Y Axis
        AxisZ_Pos : REAL;            // Z-Elevator Axis
        VacuumSensor_1 : BOOL;       // End-effector 1 vacuum confirmation
        VacuumSensor_2 : BOOL;       // End-effector 2 vacuum confirmation
        FoupPresent : BOOL;          // FOUP seating sensor
        FoupDoorOpen : BOOL;         // FOUP door status sensor
        EstopActive : BOOL;          // Emergency stop loop status
        AirPressureOK : BOOL;        // Facility CDA (Clean Dry Air) pressure
    END_STRUCT;

    // Sequencer States
    E_WaferSeqState : (
        SEQ_INIT := 0,
        SEQ_IDLE := 10,
        SEQ_CHECK_INTERLOCKS := 20,
        SEQ_DOCK_FOUP := 30,
        SEQ_OPEN_FOUP := 40,
        SEQ_MOVE_TO_SLOT := 50,
        SEQ_EXTEND_ARM := 60,
        SEQ_APPLY_VACUUM := 70,
        SEQ_CONFIRM_GRIP := 80,
        SEQ_RETRACT_ARM := 90,
        SEQ_UNDOCK_FOUP := 100,
        SEQ_COMPLETE := 110,
        SEQ_FAULT := 999
    );
END_TYPE

FUNCTION_BLOCK FB_WaferRobotSequencer
TITLE = 'Ultra-Precise Wafer Handling Robot Sequencer'
VERSION : '2.0'

VAR_INPUT
    Enable : BOOL;
    ResetFault : BOOL;
    HW_Inputs : UDT_Robot_Hardware;
END_VAR

VAR_IN_OUT
    HostComms : UDT_SECS_GEM_Interface;
END_VAR

VAR_OUTPUT
    State : E_WaferSeqState := SEQ_INIT;
    RobotBusy : BOOL;
    FaultActive : BOOL;
    VacuumValve_Cmd : BOOL;
    FoupLatch_Cmd : BOOL;
    FoupDoor_Cmd : BOOL;
    TargetX : REAL;
    TargetZ : REAL;
END_VAR

VAR
    TmrVacuumGrip : TON;             // Vacuum stabilization timer
    TmrMotionTimeout : TON;          // Axis motion timeout
    InternalError : INT;
    StepDelay : TON;
END_VAR

// =========================================================================
// MAIN LOGIC
// =========================================================================
BEGIN
    // ---------------------------------------------------------
    // 1. Critical Safety Interlocks & Continuous Monitoring
    // ---------------------------------------------------------
    IF HW_Inputs.EstopActive THEN
        InternalError := 1001; // E-Stop pressed
        State := SEQ_FAULT;
    END_IF;

    IF NOT HW_Inputs.AirPressureOK AND State <> SEQ_IDLE AND State <> SEQ_FAULT THEN
        InternalError := 1002; // CDA Pressure Loss
        State := SEQ_FAULT;
    END_IF;

    IF HostComms.HostCommand = 4 THEN // Abort command from Host
        InternalError := 1003; // Host Aborted
        State := SEQ_FAULT;
    END_IF;

    // Vacuum loss detection while holding a wafer
    IF (State >= SEQ_CONFIRM_GRIP AND State <= SEQ_UNDOCK_FOUP) AND NOT HW_Inputs.VacuumSensor_1 THEN
        InternalError := 1004; // Dropped wafer or vacuum loss
        State := SEQ_FAULT;
    END_IF;

    // ---------------------------------------------------------
    // 2. SECS/GEM State Reporting
    // ---------------------------------------------------------
    IF State = SEQ_IDLE THEN
        HostComms.EquipmentState := 1; // IDLE
    ELSIF State = SEQ_FAULT THEN
        HostComms.EquipmentState := 4; // FAULTED
    ELSE
        HostComms.EquipmentState := 2; // EXECUTING
    END_IF;

    HostComms.ErrorCode := InternalError;

    // ---------------------------------------------------------
    // 3. Sequencer State Machine
    // ---------------------------------------------------------
    CASE State OF

        SEQ_INIT:
            // Reset outputs and commands
            RobotBusy := FALSE;
            FaultActive := FALSE;
            VacuumValve_Cmd := FALSE;
            FoupLatch_Cmd := FALSE;
            FoupDoor_Cmd := FALSE;
            InternalError := 0;
            IF Enable AND NOT HW_Inputs.EstopActive THEN
                State := SEQ_IDLE;
            END_IF;

        SEQ_IDLE:
            RobotBusy := FALSE;
            // Await SECS/GEM Host Command (1 = LoadFOUP & Transfer)
            IF HostComms.HostCommand = 1 THEN
                RobotBusy := TRUE;
                HostComms.EventReport := TRUE; // Trigger CEID for Job Started
                State := SEQ_CHECK_INTERLOCKS;
            END_IF;

        SEQ_CHECK_INTERLOCKS:
            // Verify FOUP is present on the load port
            IF HW_Inputs.FoupPresent THEN
                State := SEQ_DOCK_FOUP;
            ELSE
                InternalError := 2001; // No FOUP detected
                State := SEQ_FAULT;
            END_IF;

        SEQ_DOCK_FOUP:
            FoupLatch_Cmd := TRUE;
            StepDelay(IN := TRUE, PT := T#2S);
            IF StepDelay.Q THEN
                StepDelay(IN := FALSE);
                State := SEQ_OPEN_FOUP;
            END_IF;

        SEQ_OPEN_FOUP:
            FoupDoor_Cmd := TRUE;
            IF HW_Inputs.FoupDoorOpen THEN
                State := SEQ_MOVE_TO_SLOT;
            END_IF;

        SEQ_MOVE_TO_SLOT:
            // Calculate Z height based on SECS/GEM requested slot (pitch ~10mm)
            TargetZ := 50.0 + (INT_TO_REAL(HostComms.WaferSlot) * 10.0);
            TargetX := 0.0; // Centered
            // Simulate motion complete by checking position tolerance
            IF ABS(HW_Inputs.AxisZ_Pos - TargetZ) < 0.1 THEN
                State := SEQ_EXTEND_ARM;
            END_IF;

        SEQ_EXTEND_ARM:
            TargetX := 350.0; // Reach into FOUP
            IF ABS(HW_Inputs.AxisX_Pos - TargetX) < 0.1 THEN
                State := SEQ_APPLY_VACUUM;
            END_IF;

        SEQ_APPLY_VACUUM:
            VacuumValve_Cmd := TRUE;
            TmrVacuumGrip(IN := TRUE, PT := T#500MS);
            IF TmrVacuumGrip.Q THEN
                TmrVacuumGrip(IN := FALSE);
                State := SEQ_CONFIRM_GRIP;
            END_IF;

        SEQ_CONFIRM_GRIP:
            IF HW_Inputs.VacuumSensor_1 THEN
                // Grip confirmed, lift wafer slightly to clear slot
                TargetZ := TargetZ + 2.0; 
                State := SEQ_RETRACT_ARM;
            ELSE
                InternalError := 3001; // Failed to establish vacuum
                State := SEQ_FAULT;
            END_IF;

        SEQ_RETRACT_ARM:
            TargetX := 0.0;
            IF ABS(HW_Inputs.AxisX_Pos - TargetX) < 0.1 THEN
                State := SEQ_UNDOCK_FOUP;
            END_IF;

        SEQ_UNDOCK_FOUP:
            FoupDoor_Cmd := FALSE;
            IF NOT HW_Inputs.FoupDoorOpen THEN
                FoupLatch_Cmd := FALSE;
                State := SEQ_COMPLETE;
            END_IF;

        SEQ_COMPLETE:
            HostComms.EventReport := TRUE; // Trigger CEID for Job Complete
            HostComms.HostCommand := 0;    // Clear command
            RobotBusy := FALSE;
            State := SEQ_IDLE;

        SEQ_FAULT:
            FaultActive := TRUE;
            RobotBusy := FALSE;
            // Safe hardware state
            TargetX := 0.0;
            IF ResetFault THEN
                InternalError := 0;
                State := SEQ_INIT;
            END_IF;

    END_CASE;

END_FUNCTION_BLOCK
```

FUNCTION_BLOCK "FB_Coaster_Block_Zone_SIL4"
TITLE = 'SIL-4 Roller Coaster Block Zone Controller'
AUTHOR : 'Lumina Elite'
VERSION : '3.0'
// -----------------------------------------------------------------------------
// DESCRIPTION:
// SIL-4 compliant Block Zone Controller for Theme Park Roller Coasters.
// Incorporates redundant wheel-sensor tracking, anti-rollback monitoring,
// and fail-safe magnetic brake deployment. 
// Uses a complex state machine for block occupancy and train progression.
// -----------------------------------------------------------------------------

VAR_INPUT
    xEnable : BOOL; // System enable
    xEStop_Ch1 : BOOL; // E-Stop Channel 1 (Normally Closed)
    xEStop_Ch2 : BOOL; // E-Stop Channel 2 (Normally Closed)
    xReset_SIL : BOOL; // Safety Reset

    // Redundant Wheel Sensors (Train Entry)
    xWheelSens_Entry_A : BOOL;
    xWheelSens_Entry_B : BOOL;

    // Redundant Wheel Sensors (Train Exit)
    xWheelSens_Exit_A : BOOL;
    xWheelSens_Exit_B : BOOL;

    // Anti-Rollback Ratchet Monitoring
    xAntiRollback_Dog1 : BOOL;
    xAntiRollback_Dog2 : BOOL;

    // Previous and Next Block Status (SIL-3/4 Communication)
    xNextBlockClear : BOOL;
    xPrevBlockOccupied : BOOL;

    // Environment / Hardware interlocks
    xThermalOverload_Brake : BOOL;
    xDrivePowerOK : BOOL;
END_VAR

VAR_OUTPUT
    xBlockOccupied : BOOL; // Safe Block Occupied Status
    xDeployBrakes : BOOL; // Fail-Safe Magnetic Brake Deployment (TRUE = Apply Brakes)
    xDriveEnable : BOOL; // Enable LSM or Friction Wheels
    xAntiRollbackEngage : BOOL; // Engage Anti-Rollback mechanism
    xSystemFault : BOOL; // Fault flag
    wFaultCode : WORD; // Fault code for diagnostics
END_VAR

VAR
    // State Machine
    eBlockState : INT;
    // Constants for State Machine
    ST_INIT : INT := 0;
    ST_IDLE : INT := 10;
    ST_ENTRY_DETECT : INT := 20;
    ST_OCCUPIED : INT := 30;
    ST_DISPATCH_WAIT : INT := 40;
    ST_EXIT_DETECT : INT := 50;
    ST_FAULT : INT := 99;

    // Internal Timers
    fbSensorDiscrepancyTimer_Entry : TON;
    fbSensorDiscrepancyTimer_Exit : TON;
    fbRollbackTimer : TON;

    // Safety & Redundancy Flags
    xSafeEStop : BOOL;
    xSafeEntrySensors : BOOL;
    xSafeExitSensors : BOOL;

    // Edge Detection
    r_trig_Entry : R_TRIG;
    r_trig_Exit : R_TRIG;
END_VAR

BEGIN
    // -------------------------------------------------------------------------
    // 1. SAFETY & REDUNDANCY EVALUATION
    // -------------------------------------------------------------------------

    // Cross-check E-Stop channels
    xSafeEStop := xEStop_Ch1 AND xEStop_Ch2;
    IF (xEStop_Ch1 <> xEStop_Ch2) THEN
        wFaultCode := 16#E001; // E-Stop Discrepancy
        eBlockState := ST_FAULT;
    END_IF;

    // Sensor Discrepancy Evaluation (Entry)
    fbSensorDiscrepancyTimer_Entry(IN := (xWheelSens_Entry_A <> xWheelSens_Entry_B), PT := T#50ms);
    IF fbSensorDiscrepancyTimer_Entry.Q THEN
        wFaultCode := 16#S001; // Entry Sensor Discrepancy
        eBlockState := ST_FAULT;
    END_IF;
    xSafeEntrySensors := xWheelSens_Entry_A AND xWheelSens_Entry_B;

    // Sensor Discrepancy Evaluation (Exit)
    fbSensorDiscrepancyTimer_Exit(IN := (xWheelSens_Exit_A <> xWheelSens_Exit_B), PT := T#50ms);
    IF fbSensorDiscrepancyTimer_Exit.Q THEN
        wFaultCode := 16#S002; // Exit Sensor Discrepancy
        eBlockState := ST_FAULT;
    END_IF;
    xSafeExitSensors := xWheelSens_Exit_A AND xWheelSens_Exit_B;

    // Hardware interlocks
    IF xThermalOverload_Brake OR NOT xDrivePowerOK THEN
        wFaultCode := 16#H001; // Hardware failure
        eBlockState := ST_FAULT;
    END_IF;

    // Edge Detectors for Train Movement
    r_trig_Entry(CLK := xSafeEntrySensors);
    r_trig_Exit(CLK := xSafeExitSensors);

    // -------------------------------------------------------------------------
    // 2. BLOCK ZONE STATE MACHINE
    // -------------------------------------------------------------------------

    CASE eBlockState OF

        ST_INIT:
            // Initialization and Safety Checks
            xDeployBrakes := TRUE; // Fail-safe state
            xDriveEnable := FALSE;
            xAntiRollbackEngage := TRUE;
            xSystemFault := FALSE;
            wFaultCode := 16#0000;

            IF xSafeEStop AND xEnable AND xReset_SIL THEN
                eBlockState := ST_IDLE;
            END_IF;

        ST_IDLE:
            // Block is clear and waiting for train
            xBlockOccupied := FALSE;
            xDeployBrakes := FALSE; 
            xDriveEnable := FALSE;
            xAntiRollbackEngage := FALSE;

            IF r_trig_Entry.Q THEN
                eBlockState := ST_ENTRY_DETECT;
            END_IF;

        ST_ENTRY_DETECT:
            // Train is currently traversing entry sensors
            xBlockOccupied := TRUE;
            // Immediate Anti-Rollback engagement during entry phase to prevent back-slip
            xAntiRollbackEngage := TRUE;

            // Assume train fully entered after sensors clear or specific sequence
            IF NOT xSafeEntrySensors THEN
                eBlockState := ST_OCCUPIED;
            END_IF;

        ST_OCCUPIED:
            // Train fully inside the block
            xBlockOccupied := TRUE;
            xAntiRollbackEngage := TRUE;

            // Determine if it is safe to proceed
            IF xNextBlockClear THEN
                xDeployBrakes := FALSE;
                eBlockState := ST_DISPATCH_WAIT;
            ELSE
                // Block violation ahead, immediately deploy fail-safe magnetic brakes
                xDeployBrakes := TRUE; 
                xDriveEnable := FALSE;
            END_IF;

        ST_DISPATCH_WAIT:
            xBlockOccupied := TRUE;
            xDeployBrakes := FALSE;
            xAntiRollbackEngage := FALSE; // Release rollback for forward motion
            xDriveEnable := TRUE; // Enable LSM drives for dispatch

            // Monitor for Exit
            IF r_trig_Exit.Q THEN
                eBlockState := ST_EXIT_DETECT;
            END_IF;

            // Anti-rollback check during dispatch (if train rolls back unexpectedly)
            fbRollbackTimer(IN := xAntiRollback_Dog1 OR xAntiRollback_Dog2, PT := T#500ms);
            IF fbRollbackTimer.Q AND NOT xNextBlockClear THEN
                wFaultCode := 16#R001; // Rollback detected without clearance
                eBlockState := ST_FAULT;
            END_IF;

        ST_EXIT_DETECT:
            // Train is currently exiting the block
            xBlockOccupied := TRUE;
            xDriveEnable := FALSE; // Drive responsibility handed to next block

            IF NOT xSafeExitSensors THEN
                // Train has completely left the block
                eBlockState := ST_IDLE;
            END_IF;

        ST_FAULT:
            // Critical Fail-Safe State
            xSystemFault := TRUE;
            xDeployBrakes := TRUE; // Immediate Magnetic Brake Deployment
            xDriveEnable := FALSE;
            xAntiRollbackEngage := TRUE;
            xBlockOccupied := TRUE; // Assume occupied during fault

            IF xSafeEStop AND xReset_SIL THEN
                // Only allow reset if fault conditions are cleared
                eBlockState := ST_INIT;
            END_IF;

    END_CASE;

    // -------------------------------------------------------------------------
    // 3. GLOBAL FAIL-SAFE OVERRIDES
    // -------------------------------------------------------------------------

    IF NOT xSafeEStop OR eBlockState = ST_FAULT THEN
        xDeployBrakes := TRUE;
        xDriveEnable := FALSE;
        xAntiRollbackEngage := TRUE;
    END_IF;

END_FUNCTION_BLOCK

