    diLastEnc1         : DINT;
    diLastEnc2         : DINT;

    // Constants for Abstraction
    ENCODER_PPR        : REAL := 1024.0; // Pulses per revolution
    PUMP_K_FACTOR      : REAL := 0.005; // RPM to LPM approximation factor
END_VAR

BEGIN
    // ==========================================================================
    // 1. SAFETY & INTERLOCK ABSTRACTION
    // ==========================================================================
    // Check for E-Stop (Active Low) or Thermal Overload
    IF NOT xEmergencyStop OR xThermalOverload THEN
        iState := 99;
        IF NOT xEmergencyStop THEN wFaultCode := 16#F001; END_IF; // E-Stop
        IF xThermalOverload THEN wFaultCode := 16#F002; END_IF;   // Thermal
    END_IF;

    // Ultrasonic Bubble Detection - Immediate Safe State
    IF xUltrasonicBubble THEN
        iState := 99;
        wFaultCode := 16#E001; // Critical Air Embolism Risk
    END_IF;

    // Hemolysis & Cavitation Prevention
    xCavitationRisk := (rPrePumpPress < rMinInletPressLim);
    xHemolysisRisk  := ((rPostPumpPress - rPrePumpPress) > rMaxDeltaPressLim);

    IF xCavitationRisk THEN
        iState := 99;
        wFaultCode := 16#E002; // Cavitation Risk Detected
    ELSIF xHemolysisRisk THEN
        iState := 99;
        wFaultCode := 16#E003; // Hemolysis Risk Detected
    END_IF;

    // ==========================================================================
    // 2. DUAL-REDUNDANT ENCODER TRACKING & FLOW ESTIMATION
    // ==========================================================================
    // Delta calculations (simplified approximation assuming 1 second sample time)
    rActualRPM1 := DINT_TO_REAL(diEncoder1Count - diLastEnc1) * (60.0 / ENCODER_PPR);
    rActualRPM2 := DINT_TO_REAL(diEncoder2Count - diLastEnc2) * (60.0 / ENCODER_PPR);

    diLastEnc1 := diEncoder1Count;
    diLastEnc2 := diEncoder2Count;

    // Cross-check redundant sensors
    IF ABS(rActualRPM1 - rActualRPM2) > 50.0 THEN // 50 RPM discrepancy threshold
        xEncoderMismatch := TRUE;
        iState := 99;
        wFaultCode := 16#E004; // Encoder discrepancy / Hardware failure
    ELSE
        xEncoderMismatch := FALSE;
        rAverageRPM := (rActualRPM1 + rActualRPM2) / 2.0;
        rEstimatedFlowLPM := rAverageRPM * PUMP_K_FACTOR; // Derived clinical flow
    END_IF;

    // ==========================================================================
    // 3. ECMO PUMP STATE MACHINE
    // ==========================================================================
    CASE iState OF
        0: // INIT / SAFE STATE
            rCommandRPM := 0.0;
            xPumpRunning := FALSE;
            xSafeStateActive := TRUE;

            // Wait for clearances and run command
            IF xEnableRun AND xEmergencyStop AND NOT xThermalOverload 
               AND NOT xUltrasonicBubble AND NOT xEncoderMismatch THEN
                iState := 10;
                xSafeStateActive := FALSE;
                wFaultCode := 16#0000;
            END_IF;

        10: // STANDBY
            rCommandRPM := 0.0;
            IF xEnableRun AND rTargetRPM > 0.0 THEN
                iState := 20;
            ELSIF NOT xEnableRun THEN
                iState := 0;
            END_IF;

        20: // RAMP_UP (Controlled acceleration for patient safety)
            IF rCommandRPM < rTargetRPM THEN
                // Slew rate limited acceleration (e.g. 100 RPM per scan/cycle)
                rCommandRPM := rCommandRPM + 100.0; 
                xPumpRunning := TRUE;
            ELSE
                iState := 30;
            END_IF;

            // Check for stop request
            IF NOT xEnableRun THEN
                iState := 0;
            END_IF;

        30: // RUN_CONTINUOUS
            rCommandRPM := rTargetRPM; // Maintain target speed
            xPumpRunning := TRUE;

            IF NOT xEnableRun THEN
                iState := 0;
            END_IF;

        99: // FAULT HANDLING
            // Halt pump immediately to prevent patient harm
            rCommandRPM := 0.0;
            xPumpRunning := FALSE;
            xSafeStateActive := TRUE;

            IF xResetFaults AND NOT xUltrasonicBubble AND NOT xCavitationRisk 
               AND NOT xHemolysisRisk AND xEmergencyStop THEN
                iState := 0; // Return to INIT after acknowledgement and clearing
                wFaultCode := 16#0000;
            END_IF;

        ELSE
            iState := 99; // Fallback for unknown states
    END_CASE;

END_FUNCTION_BLOCK

