`iecst
(* 
   =================================================================================================
   DEEP SEA ROV SUBSEA CONTROL MODULE (SCM)
   =================================================================================================
   Architecture: IEC 61131-3 Structured Text
   Application: 6000m rated Work-Class Remotely Operated Vehicle (ROV)

   Features:
   1. Hydraulic Pressure Compensation (ambient + 1 bar overhead) for 6000m depth (~600 Bar).
   2. Umbilical Fiber-Optic Telemetry Heartbeat / Liveness checks.
   3. Thruster Vectoring Matrices for 6-DOF control (Surge, Sway, Heave, Roll, Pitch, Yaw).
   4. Complex state machine with automated fault detection and safety interlocks (E-Stops, Thermal).
   =================================================================================================
*)

TYPE ROV_STATE :
(
    ST_INIT := 0,
    ST_STANDBY := 1,
    ST_SYSTEM_CHECK := 2,
    ST_SURFACE_TETHERED := 3,
    ST_DESCENT := 4,
    ST_SUBSEA_OPS := 5,
    ST_ASCENT := 6,
    ST_SAFE_STATE_FAULT := 7,
    ST_EMERGENCY_RECOVERY := 8
);
END_TYPE

TYPE THRUSTER_COMMANDS :
STRUCT
    Surge : REAL; (* X-Axis Translation *)
    Sway  : REAL; (* Y-Axis Translation *)
    Heave : REAL; (* Z-Axis Translation *)
    Roll  : REAL; (* X-Axis Rotation *)
    Pitch : REAL; (* Y-Axis Rotation *)
    Yaw   : REAL; (* Z-Axis Rotation *)
END_STRUCT;
END_TYPE

TYPE THRUSTER_OUTPUTS :
STRUCT
    HL : REAL; (* Horizontal Left *)
    HR : REAL; (* Horizontal Right *)
    VL : REAL; (* Vertical Left *)
    VR : REAL; (* Vertical Right *)
    LTL : REAL; (* Lateral Top Left *)
    LTR : REAL; (* Lateral Top Right *)
END_STRUCT;
END_TYPE

FUNCTION_BLOCK FB_ThrusterVectoring
VAR_INPUT
    Cmd : THRUSTER_COMMANDS;
    MaxRPM : REAL := 3000.0;
END_VAR
VAR_OUTPUT
    Out : THRUSTER_OUTPUTS;
END_VAR
VAR
    (* Transformation Matrix Coefficients based on ROV Thruster Geometry *)
    Coef_Surge_HL : REAL := 1.0;
    Coef_Surge_HR : REAL := 1.0;
    Coef_Sway_LTL : REAL := 1.0;
    Coef_Sway_LTR : REAL := 1.0;
    Coef_Heave_VL : REAL := 1.0;
    Coef_Heave_VR : REAL := 1.0;
END_VAR
(* Calculate Matrix allocations for each thruster using linear superposition *)
Out.HL := (Cmd.Surge * Coef_Surge_HL) + (Cmd.Yaw * 0.5);
Out.HR := (Cmd.Surge * Coef_Surge_HR) - (Cmd.Yaw * 0.5);
Out.VL := (Cmd.Heave * Coef_Heave_VL) + (Cmd.Roll * 0.5) - (Cmd.Pitch * 0.5);
Out.VR := (Cmd.Heave * Coef_Heave_VR) - (Cmd.Roll * 0.5) - (Cmd.Pitch * 0.5);
Out.LTL := (Cmd.Sway * Coef_Sway_LTL) + (Cmd.Yaw * 0.25);
Out.LTR := (Cmd.Sway * Coef_Sway_LTR) - (Cmd.Yaw * 0.25);

(* Saturate outputs to MaxRPM *)
Out.HL := LIMIT(-MaxRPM, Out.HL, MaxRPM);
Out.HR := LIMIT(-MaxRPM, Out.HR, MaxRPM);
Out.VL := LIMIT(-MaxRPM, Out.VL, MaxRPM);
Out.VR := LIMIT(-MaxRPM, Out.VR, MaxRPM);
Out.LTL := LIMIT(-MaxRPM, Out.LTL, MaxRPM);
Out.LTR := LIMIT(-MaxRPM, Out.LTR, MaxRPM);
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_TelemetryHeartbeat
VAR_INPUT
    RxHeartbeat : BOOL;
    TimeoutMS : TIME := T#500ms;
END_VAR
VAR_OUTPUT
    LinkActive : BOOL;
    FaultComm : BOOL;
END_VAR
VAR
    Timer : TON;
    PrevHeartbeat : BOOL;
END_VAR
Timer(IN := (RxHeartbeat = PrevHeartbeat), PT := TimeoutMS);
PrevHeartbeat := RxHeartbeat;

IF Timer.Q THEN
    LinkActive := FALSE;
    FaultComm := TRUE;
ELSE
    LinkActive := TRUE;
    FaultComm := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Compensator
VAR_INPUT
    Depth_Meters : REAL;
    HydraulicSysPress_Bar : REAL;
END_VAR
VAR_OUTPUT
    TargetCompPress_Bar : REAL;
    CompensatorFault : BOOL;
    PumpDriveSignal : REAL;
END_VAR
VAR
    AmbientPress_Bar : REAL;
    Overhead_Bar : REAL := 1.0; (* 1 Bar overhead above ambient to prevent water ingress *)
    Error : REAL;
    Kp : REAL := 2.5;
END_VAR
(* 10 meters of seawater is approximately 1 Bar *)
AmbientPress_Bar := (Depth_Meters / 10.0) + 1.0; (* +1 for atmospheric at surface *)
TargetCompPress_Bar := AmbientPress_Bar + Overhead_Bar;

Error := TargetCompPress_Bar - HydraulicSysPress_Bar;
PumpDriveSignal := Error * Kp;
PumpDriveSignal := LIMIT(0.0, PumpDriveSignal, 100.0);

(* Fault detection if pressure drops below ambient - critical failure risk (water ingress) *)
IF HydraulicSysPress_Bar < AmbientPress_Bar THEN
    CompensatorFault := TRUE;
ELSE
    CompensatorFault := FALSE;
END_IF;
END_FUNCTION_BLOCK

PROGRAM MAIN_ROV_SCM
VAR
    (* State Machine *)
    CurrentState : ROV_STATE := ST_INIT;

    (* I/O and Hardware Abstraction *)
    DepthSensor_M : REAL; (* Mapped to Analog Input *)
    HydraulicPressure_Bar : REAL; (* Mapped to Analog Input *)
    FiberOpticHeartbeat_Rx : BOOL; (* Mapped to Digital Input *)
    E_Stop_Surface : BOOL;
    E_Stop_Subsea : BOOL;
    MotorTempHigh : BOOL;

    (* Control Instances *)
    ThrusterCtrl : FB_ThrusterVectoring;
    PilotCmd : THRUSTER_COMMANDS;
    ThrusterOut : THRUSTER_OUTPUTS;

    TelemetryCtrl : FB_TelemetryHeartbeat;
    LinkActive : BOOL;
    TelemetryFault : BOOL;

    CompensatorCtrl : FB_Compensator;
    CompensatorFault : BOOL;
    HydraulicPumpCmd : REAL;

    (* Safety Interlocks *)
    CriticalFault : BOOL;
    SystemSafe : BOOL;
END_VAR

(* 1. Hardware abstraction & Data Acquisition would occur here (scaling AI/DI to engineering units) *)

(* 2. Umbilical Fiber-Optic Telemetry Heartbeat *)
TelemetryCtrl(RxHeartbeat := FiberOpticHeartbeat_Rx, TimeoutMS := T#1000ms);
LinkActive := TelemetryCtrl.LinkActive;
TelemetryFault := TelemetryCtrl.FaultComm;

(* 3. Hydraulic Pressure Compensation (6000m rated) *)
CompensatorCtrl(
    Depth_Meters := DepthSensor_M, 
    HydraulicSysPress_Bar := HydraulicPressure_Bar
);
HydraulicPumpCmd := CompensatorCtrl.PumpDriveSignal;
CompensatorFault := CompensatorCtrl.CompensatorFault;

(* 4. Safety Interlocks Evaluation *)
CriticalFault := TelemetryFault OR CompensatorFault OR E_Stop_Surface OR E_Stop_Subsea OR MotorTempHigh;
SystemSafe := NOT CriticalFault;

(* 5. SCM State Machine *)
CASE CurrentState OF
    ST_INIT:
        (* Initialize variables, check sensor presence *)
        IF SystemSafe THEN
            CurrentState := ST_SYSTEM_CHECK;
        END_IF;

    ST_SYSTEM_CHECK:
        (* Perform self-test routines, verify actuator responses *)
        IF CriticalFault THEN
            CurrentState := ST_SAFE_STATE_FAULT;
        ELSIF SystemSafe AND LinkActive THEN
            CurrentState := ST_STANDBY;
        END_IF;

    ST_STANDBY:
        IF CriticalFault THEN
            CurrentState := ST_SAFE_STATE_FAULT;
        ELSIF DepthSensor_M > 10.0 THEN
            CurrentState := ST_DESCENT;
        END_IF;

    ST_DESCENT:
        IF CriticalFault THEN
            CurrentState := ST_EMERGENCY_RECOVERY;
        ELSIF DepthSensor_M > 5900.0 THEN
            CurrentState := ST_SUBSEA_OPS;
        END_IF;

    ST_SUBSEA_OPS:
        (* Main operating mode at 6000m *)
        IF CriticalFault THEN
            CurrentState := ST_EMERGENCY_RECOVERY;
        ELSIF DepthSensor_M < 100.0 THEN
            CurrentState := ST_ASCENT;
        END_IF;

    ST_ASCENT:
        IF SystemSafe AND DepthSensor_M <= 10.0 THEN
            CurrentState := ST_STANDBY;
        END_IF;

    ST_EMERGENCY_RECOVERY:
        (* Drop weights, surface immediately, override non-critical locks *)
        ThrusterOut.VL := 3000.0; (* Full heave up *)
        ThrusterOut.VR := 3000.0;
        IF DepthSensor_M <= 10.0 THEN
            CurrentState := ST_SAFE_STATE_FAULT;
        END_IF;

    ST_SAFE_STATE_FAULT:
        (* Secure all outputs, isolate hydraulics, wait for intervention *)
        ThrusterOut.HL := 0.0;
        ThrusterOut.HR := 0.0;
        ThrusterOut.VL := 0.0;
        ThrusterOut.VR := 0.0;
        ThrusterOut.LTL := 0.0;
        ThrusterOut.LTR := 0.0;
        HydraulicPumpCmd := 0.0;

        IF SystemSafe THEN (* Requires manual reset of faults *)
            CurrentState := ST_INIT;
        END_IF;
END_CASE;

(* 6. Thruster Vectoring Matrix (Only in active subsea modes) *)
IF CurrentState = ST_SUBSEA_OPS OR CurrentState = ST_DESCENT OR CurrentState = ST_STANDBY THEN
    ThrusterCtrl(Cmd := PilotCmd, MaxRPM := 3000.0);
    ThrusterOut := ThrusterCtrl.Out;
ELSIF CurrentState = ST_SAFE_STATE_FAULT THEN
    (* Handled in state machine *)
END_IF;

(* 7. Output mapping back to hardware occurs here *)
END_PROGRAM
