TYPE eTBM_Mode : (
    MODE_OFF,
    MODE_STANDBY,
    MODE_EXCAVATION,
    MODE_RING_ERECTION,
    MODE_MAINTENANCE,
    MODE_FAULT
); END_TYPE

TYPE eErector_State : (
    ERECT_IDLE,
    ERECT_PICKUP_SEGMENT,
    ERECT_MOVE_TO_POSITION,
    ERECT_PLACE_SEGMENT,
    ERECT_BOLT_SEGMENT,
