); END_TYPE

TYPE stSafetyInterlocks : STRUCT
    xEstopOk           : BOOL; // Master Emergency Stop loop
    xGasLevelOk        : BOOL; // Methane/H2S within safe limits
    xHydraulicPressOk  : BOOL; // Main hydraulic power pack pressure
    xCoolingFlowOk     : BOOL; // Cooling water flow for drives/gearboxes
    xPowerGridOk       : BOOL; // High voltage grid stability
END_STRUCT; END_TYPE

TYPE stDriveFeedback : STRUCT
    xRunning     : BOOL;
    xFault       : BOOL;
    rSpeedAct    : REAL; // RPM
    rTorqueAct   : REAL; // Nm
    rTempAct     : REAL; // Celsius
END_STRUCT; END_TYPE

//==============================================================================
// FUNCTION BLOCK: Drive Hardware Abstraction
//==============================================================================
FUNCTION_BLOCK FB_VFD_Drive
VAR_INPUT
    xEnable       : BOOL;
    rSpeedCmd     : REAL;
    rTorqueLimit  : REAL;
    xReset        : BOOL;
    xThermalTrip  : BOOL; // Hardware thermal overload
END_VAR
VAR_OUTPUT
    stStatus      : stDriveFeedback;
END_VAR
VAR
    fbStartTimer  : TON;
    fbStopTimer   : TON;
END_VAR
BEGIN
    // Simplified VFD hardware abstraction logic
    IF xThermalTrip THEN
        stStatus.xFault := TRUE;
        stStatus.xRunning := FALSE;
        stStatus.rSpeedAct := 0.0;
        stStatus.rTorqueAct := 0.0;
    ELSIF xReset THEN
        stStatus.xFault := FALSE;
    END_IF;

    IF xEnable AND NOT stStatus.xFault THEN
        stStatus.xRunning := TRUE;
        stStatus.rSpeedAct := rSpeedCmd; // Simulated feedback
        stStatus.rTorqueAct := rTorqueLimit * 0.8; // Simulated load
    ELSE
        stStatus.xRunning := FALSE;
        stStatus.rSpeedAct := 0.0;
        stStatus.rTorqueAct := 0.0;
    END_IF;
END_FUNCTION_BLOCK

//==============================================================================
// FUNCTION BLOCK: PID Controller (Simplified for illustration)
//==============================================================================
FUNCTION_BLOCK FB_EPB_PID
VAR_INPUT
    rSetpoint   : REAL;
    rProcessVal : REAL;
    xEnable     : BOOL;
    rKp, rKi    : REAL;
END_VAR
VAR_OUTPUT
    rOutput     : REAL;
END_VAR
VAR
    rError      : REAL;
    rIntegral   : REAL;
END_VAR
BEGIN
    IF NOT xEnable THEN
        rOutput := 0.0;
        rIntegral := 0.0;
        RETURN;
    END_IF;

    rError := rSetpoint - rProcessVal;
    rIntegral := rIntegral + (rError * rKi);
    rOutput := (rError * rKp) + rIntegral;

    // Clamp output to 0-100%
    IF rOutput > 100.0 THEN rOutput := 100.0; END_IF;
    IF rOutput < 0.0 THEN rOutput := 0.0; END_IF;
END_FUNCTION_BLOCK

//==============================================================================
// MAIN FUNCTION BLOCK: TBM Controller
//==============================================================================
FUNCTION_BLOCK FB_TBM_Master
VAR_INPUT
    // Operator Commands
    xCmdStartExcavation : BOOL;
    xCmdStopExcavation  : BOOL;
    xCmdStartErector    : BOOL;
    xCmdReset           : BOOL;

    // Process Variables
    rFacePressureActual : REAL; // Current soil pressure at the cutterhead (Bar)
    rFacePressureSP     : REAL; // Desired EPB balance pressure (Bar)
    iTotalRingSegments  : INT;  // Number of segments per ring (e.g., 6 + 1 key)

    // Safety Hardware Inputs
    stSafety            : stSafetyInterlocks;
    xMotorThermals      : ARRAY[1..4] OF BOOL; // True = Overload tripped
END_VAR

VAR_OUTPUT
    eCurrentMode        : eTBM_Mode;
    eErectorState       : eErector_State;
    xMasterFault        : BOOL;
    iSegmentsPlaced     : INT;

    // Actuator Commands
    rCutterSpeedCmd     : REAL;
    rScrewConveyorCmd   : REAL; // % speed for soil extraction
END_VAR

VAR
    // Sub-modules
    aCutterDrives       : ARRAY[1..4] OF FB_VFD_Drive;
    fbFacePressurePID   : FB_EPB_PID;

    // Internal State
    xInterlocksOk       : BOOL;
    rAvgTorque          : REAL;
    i                   : INT;

    // Timers
    fbErectorTimer      : TON;
END_VAR

BEGIN
    // =========================================================================
    // 1. SAFETY & INTERLOCK MATRIX EVALUATION
    // =========================================================================
    xInterlocksOk := stSafety.xEstopOk AND 
                     stSafety.xGasLevelOk AND 
                     stSafety.xHydraulicPressOk AND 
                     stSafety.xCoolingFlowOk AND 
                     stSafety.xPowerGridOk;

    IF NOT xInterlocksOk THEN
        xMasterFault := TRUE;
        eCurrentMode := MODE_FAULT;
    END_IF;

    // Fault Reset Logic
    IF xMasterFault AND xInterlocksOk AND xCmdReset THEN
        xMasterFault := FALSE;
        eCurrentMode := MODE_STANDBY;
    END_IF;

    IF xMasterFault THEN
        rCutterSpeedCmd := 0.0;
        rScrewConveyorCmd := 0.0;
        RETURN; // Halt execution if critical fault exists
    END_IF;

    // =========================================================================
    // 2. MODE MANAGEMENT STATE MACHINE
    // =========================================================================
    CASE eCurrentMode OF
        MODE_STANDBY:
            IF xCmdStartExcavation THEN
                eCurrentMode := MODE_EXCAVATION;
            ELSIF xCmdStartErector THEN
                eCurrentMode := MODE_RING_ERECTION;
                eErectorState := ERECT_PICKUP_SEGMENT;
                iSegmentsPlaced := 0;
            END_IF;

        MODE_EXCAVATION:
            IF xCmdStopExcavation THEN
                eCurrentMode := MODE_STANDBY;
            END_IF;

        MODE_RING_ERECTION:
            // Ring erection cannot happen during excavation
            IF eErectorState = ERECT_COMPLETE THEN
                eCurrentMode := MODE_STANDBY;
            END_IF;
    END_CASE;

    // =========================================================================
    // 3. CUTTERHEAD MULTI-DRIVE CONTROL (EXCAVATION MODE)
    // =========================================================================
    rAvgTorque := 0.0;

    FOR i := 1 TO 4 DO
        aCutterDrives[i](
            xEnable := (eCurrentMode = MODE_EXCAVATION),
            rSpeedCmd := 2.5, // 2.5 RPM optimal boring speed
            rTorqueLimit := 50000.0, // Nm
            xReset := xCmdReset,
            xThermalTrip := xMotorThermals[i]
        );

        // Torque Distribution Monitoring
        rAvgTorque := rAvgTorque + aCutterDrives[i].stStatus.rTorqueAct;

        // If any drive faults, trigger master fault
        IF aCutterDrives[i].stStatus.xFault THEN
            xMasterFault := TRUE;
            eCurrentMode := MODE_FAULT;
        END_IF;
    END_FOR;

    rAvgTorque := rAvgTorque / 4.0;

    // =========================================================================
    // 4. EARTH-PRESSURE BALANCE (EPB) SLURRY FACE CONTROL
    // =========================================================================
    // Uses PID control on the screw conveyor to extract soil at the exact rate
    // required to maintain the desired pressure at the tunnel face.
    fbFacePressurePID(
        xEnable     := (eCurrentMode = MODE_EXCAVATION),
        rSetpoint   := rFacePressureSP,
        rProcessVal := rFacePressureActual,
        rKp         := 2.5,
        rKi         := 0.1
    );

    // Invert PID output: If pressure is high, extract soil faster (speed up screw)
    rScrewConveyorCmd := fbFacePressurePID.rOutput; 

    // =========================================================================
    // 5. SEGMENTAL CONCRETE RING ERECTOR SEQUENCING
    // =========================================================================
    IF eCurrentMode = MODE_RING_ERECTION THEN
        CASE eErectorState OF
            ERECT_IDLE:
                // Waiting for command

            ERECT_PICKUP_SEGMENT:
                // Engage vacuum lifter / mechanical grip
                fbErectorTimer(IN := TRUE, PT := T#5S); // Simulate physical action time
                IF fbErectorTimer.Q THEN
                    fbErectorTimer(IN := FALSE);
                    eErectorState := ERECT_MOVE_TO_POSITION;
                END_IF;

            ERECT_MOVE_TO_POSITION:
                // Rotate erector arm to target radial coordinate
                fbErectorTimer(IN := TRUE, PT := T#10S);
                IF fbErectorTimer.Q THEN
                    fbErectorTimer(IN := FALSE);
                    eErectorState := ERECT_PLACE_SEGMENT;
                END_IF;

            ERECT_PLACE_SEGMENT:
                // Extend thrust cylinders to press segment against previous ring
                fbErectorTimer(IN := TRUE, PT := T#3S);
                IF fbErectorTimer.Q THEN
                    fbErectorTimer(IN := FALSE);
                    eErectorState := ERECT_BOLT_SEGMENT;
                END_IF;

            ERECT_BOLT_SEGMENT:
                // Automate or manual bolting wait
                fbErectorTimer(IN := TRUE, PT := T#7S);
                IF fbErectorTimer.Q THEN
                    fbErectorTimer(IN := FALSE);
                    iSegmentsPlaced := iSegmentsPlaced + 1;

                    IF iSegmentsPlaced >= iTotalRingSegments THEN
                        eErectorState := ERECT_RETURN_HOME;
                    ELSE
                        eErectorState := ERECT_PICKUP_SEGMENT;
                    END_IF;
                END_IF;

            ERECT_RETURN_HOME:
                // Return arm to 6 o'clock position
                fbErectorTimer(IN := TRUE, PT := T#8S);
                IF fbErectorTimer.Q THEN
                    fbErectorTimer(IN := FALSE);
                    eErectorState := ERECT_COMPLETE;
                END_IF;

            ERECT_COMPLETE:
                // State cleared by Mode manager

        END_CASE;
    ELSE
        eErectorState := ERECT_IDLE;
        fbErectorTimer(IN := FALSE);
    END_IF;

END_FUNCTION_BLOCK
```

### Key Engineering Upgrades:
1. **Safety Interlock Matrix (`xInterlocksOk`)**: Replaces simple `xEnable` bits with a SIL-3 style aggregation of environmental hazards (methane/H2S levels, coolant flow, HV grid stability, hydraulic pressures).
2. **Earth-Pressure Balance (EPB) Engine**: Incorporates a closed-loop PID controller (`FB_EPB_PID`) to continuously modulate the extraction screw conveyor speed. If the face pressure is too high, the screw accelerates to remove soil faster; if it's too low, it slows down to build up a protective plug against the geology.
3. **Multi-Drive Torque Distribution**: Cutterhead load is scaled across a parameterizable array of heavy-duty VFDs (`FB_VFD_Drive`). The routine aggregates individual torques to monitor for synchronization faults or mechanical binding.
4. **Ring Erector State Machine**: Introduces a sophisticated autonomous sequencer (`eErectorState`) governing the pickup, radial rotation, placement, and bolting of multi-ton concrete segments.

